# Writes the hedra command files of the mirror-beam world: court (tiled floor, stone border, the
# west and east colonnades), temple (steps, two pylons, a gate, a hall), desert (sand floor and dunes),
# palm, sun (a striped setting sun facing the camera), crystal, stump, lens (the beam's source),
# spark, ring (the hover marker), emblem (the sun disc over the gate). Run from models/env:
#   /usr/bin/python3 make_env.py
# Up Z, front -Y (hedra). World (glTF) = (x, z, -y) of hedra. Colours exact Sunset Red.
import math

HEX = {"A": "0d101b", "B": "281a2d", "C": "6b2341", "D": "af2747", "E": "ee243d"}
def col(n):
    h = HEX[n]; r, g, b = (int(h[i:i + 2], 16) / 255 for i in (0, 2, 4))
    return f"--base-color {r:.4f} {g:.4f} {b:.4f}"

COLS, ROWS, CELL = 7, 4, 1.2           # the puzzle grid (game.as has the same numbers)
HX, HY = COLS * CELL / 2, ROWS * CELL / 2   # 4.2, 3.0
PITCH = 40                             # the camera's pitch (scene.rml): the sun faces it

files = {}

def box(name, sx, sy, sz, x, y, z, rotz=0):
    s = f"add mesh cube --name {name} --size 1 --location {x:.3f} {y:.3f} {z:.3f}\nscale {sx:.3f} {sy:.3f} {sz:.3f}\napply --scale\n"
    if rotz:
        s += f"set rotation 0 0 {rotz:.2f}\napply --rotation\n"
    return s

def del_bottom(name):
    return f"active {name}\nmode edit\nselect face where \"normal.z < -0.9\"\ndelete only-faces\nmode object\n"

# ---------------------------------------------------------------- court
cols = []
names = []
for side, x in (("W", -HX - 0.75), ("E", HX + 0.75)):
    for k in range(ROWS + 1):
        y = -HY + k * CELL
        n = f"C{side}{k}"
        cols.append(f"add mesh cylinder --name {n} --vertices 8 --radius 0.2 --depth 1.5 --location {x:.3f} {y:.3f} 0.9")
        cols.append(box(f"B{side}{k}", 0.5, 0.5, 0.16, x, y, 0.23).strip())
        cols.append(box(f"K{side}{k}", 0.54, 0.54, 0.18, x, y, 1.74).strip())
        names += [n, f"B{side}{k}", f"K{side}{k}"]
B = 0.55   # border width
files["court"] = f"""# Court: the 7 x 4 tiled floor (top at z 0, 1.2 m tiles in dark grout), a stone border around it,
# and a colonnade on the west and the east sides. Generated by make_env.py.
new
material new Tile {col('C')} --no-slot
material new Grout {col('B')} --no-slot
material new Stone {col('B')} --no-slot
material new Cap {col('C')} --no-slot
add mesh grid --name Floor --x-subdivisions {COLS} --y-subdivisions {ROWS} --size 1 --location 0 0 0
scale {COLS * CELL} {ROWS * CELL} 1
apply --scale
material assign Grout
mode edit
select all
inset 0.08 --individual
material assign Tile
mode object
{box('BorderN', 2 * HX + 2 * B, B, 0.3, 0, HY + B / 2, 0.0)}{box('BorderS', 2 * HX + 2 * B, B, 0.3, 0, -HY - B / 2, 0.0)}{box('BorderW', B, 2 * HY, 0.3, -HX - B / 2, 0, 0.0)}{box('BorderE', B, 2 * HY, 0.3, HX + B / 2, 0, 0.0)}select BorderN BorderS BorderW BorderE
active BorderN
join
rename BorderN Border
material assign Cap
mode edit
select face where "normal.z < 0.9"
material assign Stone
select face where "normal.z < -0.9"
delete only-faces
mode object
""" + "\n".join(cols) + f"""
select {' '.join(names)}
active CW0
join
rename CW0 Colonnade
material assign Stone
mode edit
select face where "normal.z > 0.9"
material assign Cap
select face where "normal.z < -0.9"
delete only-faces
mode object
select Floor Border Colonnade
shade flat
export court.glb
"""

# ---------------------------------------------------------------- temple (north, beyond the court)
ty = HY + B          # the border's north edge (hedra y)
steps = []
for i in range(3):
    steps.append(box(f"S{i}", 5.4 - i * 0.5, 1.1 - i * 0.33, 0.2, 0, ty + 0.55 + i * 0.165, 0.1 + i * 0.2))
pyl = []
for s, x in (("L", -2.0), ("R", 2.0)):
    pyl.append(f"add mesh cube --name P{s} --size 1 --location {x} {ty + 1.6} 1.4")
    pyl.append("scale 2.1 1.0 2.8\napply --scale")
    pyl.append(f"mode edit\nselect vert where \"pos.z > 1\"\nscale 0.84 0.8 1\nmode object")
    pyl.append(box(f"T{s}", 1.95, 0.95, 0.2, x, ty + 1.6, 2.9).strip())
files["temple"] = f"""# Temple: three steps up from the court's north border, two tapering pylons with cornices, a lintel
# over a dark gate, a hall behind. Generated by make_env.py.
new
material new Stone {col('B')} --no-slot
material new Cap {col('C')} --no-slot
material new Door {col('A')} --no-slot
""" + "".join(steps) + "\n".join(pyl) + f"""
{box('Lintel', 2.3, 0.85, 0.42, 0, ty + 1.6, 2.3)}{box('Door', 1.9, 0.2, 2.1, 0, ty + 1.75, 1.05)}{box('Hall', 5.6, 1.5, 1.8, 0, ty + 2.7, 0.9)}{box('Roof', 5.8, 1.7, 0.18, 0, ty + 2.7, 1.89)}select S0 S1 S2 PL PR TL TR Lintel Hall Roof
active S0
join
rename S0 Temple
material assign Stone
mode edit
select face where "normal.z > 0.9"
material assign Cap
select face where "normal.z < -0.9"
delete only-faces
mode object
select Door
material assign Door
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object
select Temple Door
shade flat
export temple.glb
"""

# ---------------------------------------------------------------- desert (sand floor and dunes)
dunes = []
import random
rnd = random.Random(4)
spots = [(-7.6, 6.2, 1.6, 0.5), (7.4, 6.0, 1.8, 0.7), (-8.8, 3.6, 1.6, 0.45), (8.8, 3.4, 1.6, 0.5)]
for i, (x, y, r, h) in enumerate(spots):
    dunes.append(f"add mesh ico-sphere --name D{i} --subdivisions 2 --radius 1 --location {x} {y} 0")
    dunes.append(f"scale {r * 1.5:.2f} {r:.2f} {h:.2f}\napply --scale")
dn = " ".join(f"D{i}" for i in range(len(spots)))
files["desert"] = f"""# Desert: the sand floor around the court (a faceted grid just below the border, open under the court) and dunes behind
# and beside the temple. Generated by make_env.py.
new
material new Sand {col('B')} --no-slot
add mesh grid --name Sand --x-subdivisions 12 --y-subdivisions 9 --size 1 --location 0 0.6875 -0.03
scale 18 12.375 1
apply --scale
apply --location
mode edit
# no sand under the court: its grid lines meet at x +-4.5, y +-2.75, inside the court's border
select face where "abs(pos.x) < 4.5 && abs(pos.y) < 2.75"
delete only-faces
select vert where "abs(pos.x) > 5.9 || pos.y < -4.6 || pos.y > 6.9"
randomize --amount 0.06 --seed 3
mode object
""" + "\n".join(dunes) + f"""
select Sand {dn}
active Sand
join
material assign Sand
mode edit
select vert where "pos.z < -0.15 && (abs(pos.x) > 5.9 || pos.y > 5.5)"
delete vert
select vert where "abs(pos.x) > 5.9 || pos.y > 5.5"
randomize --amount 0.12 --seed 9
mode object
shade flat
export desert.glb
"""

# ---------------------------------------------------------------- palm
trunk = []
x = y = 0.0
for i in range(6):
    r = 0.15 - i * 0.012
    trunk.append(f"add mesh cylinder --name T{i} --vertices 6 --radius {r:.3f} --depth 0.5 --location {x:.3f} {y:.3f} {0.25 + i * 0.45:.3f}")
    x += 0.07 + i * 0.012
top = (x, y, 0.25 + 5 * 0.45 + 0.25)
fr = []
for i in range(7):
    a = i * 360 / 7 + 10
    fr.append(f"add mesh cube --name F{i} --size 1 --location 0 0 0")
    fr.append("scale 1.5 0.34 0.05\napply --scale")
    fr.append("mode edit\nselect vert where \"abs(pos.x) > 0.7\"\nscale 1 0.25 1\nselect vert where \"pos.x > 0.7\"\ntranslate 0 0 -0.45\nmode object")
    fr.append(f"set location 0.75 0 0\napply --location")
    fr.append(f"set rotation 0 -{18 + (i % 2) * 10} 0\napply --rotation\nset rotation 0 0 {a:.1f}\napply --rotation")
    fr.append(f"set location {top[0]:.3f} {top[1]:.3f} {top[2]:.3f}\napply --location")
files["palm"] = f"""# Palm: a leaning six-segment trunk and seven drooping fronds. Generated by make_env.py.
new
material new Bark {col('A')} --no-slot
material new Frond {col('B')} --no-slot
""" + "\n".join(trunk) + "\n" + f"""select {' '.join(f'T{i}' for i in range(6))}
active T0
join
rename T0 Trunk
material assign Bark
""" + "\n".join(fr) + f"""
select {' '.join(f'F{i}' for i in range(7))}
active F0
join
rename F0 Fronds
material assign Frond
select Trunk Fronds
shade flat
export palm.glb
"""

# ---------------------------------------------------------------- sun: a striped disc facing the camera
R = 0.95
strips = []
yv = R
k = 0
# from the top: solid strips, then strips with widening gaps (the classic setting sun)
bands = [(0.28, 0)] * 3 + [(0.2, 0.2), (0.16, 0.22), (0.12, 0.24)]
for h, gap in bands:
    y1 = yv - h
    if y1 < -R:
        break
    ym = (yv + y1) / 2
    w = 2 * math.sqrt(max(0.0, R * R - (ym) ** 2)) + 0.05
    strips.append(box(f"S{k}", w, 0.12, h + (0.02 if gap == 0 else 0), 0, 0, ym))
    k += 1
    yv = y1 - gap
files["sun"] = f"""# Sun: a disc of horizontal strips, solid at the top, cut by widening gaps below (a setting sun),
# tilted back {PITCH} degrees to face the camera. Generated by make_env.py.
new
material new Sun {col('E')} --no-slot
""" + "".join(strips) + f"""select {' '.join(f'S{i}' for i in range(k))}
active S0
join
rename S0 Sun
material assign Sun
set rotation {-PITCH} 0 0
apply --rotation
shade flat
export sun.glb
"""

# ---------------------------------------------------------------- crystal (one model: dim and lit copies)
files["crystal"] = f"""# Crystal: three hexagonal shards (bipyramids) on a low hexagonal plinth. The scene bakes it twice:
# dark (ember) and glowing (glow, unlit). Generated by make_env.py.
new
material new Plinth {col('B')} --no-slot
material new Shard {col('C')} --no-slot
add mesh cylinder --name Plinth --vertices 6 --radius 0.3 --depth 0.18 --location 0 0 0.09
material assign Plinth
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object
add mesh cylinder --name M0 --vertices 6 --radius 0.17 --depth 0.5 --location 0 0 0.43
add mesh cone --name M1 --vertices 6 --radius1 0.17 --radius2 0 --depth 0.36 --location 0 0 0.86
add mesh cylinder --name A0 --vertices 6 --radius 0.1 --depth 0.26 --location 0 0 0.13
add mesh cone --name A1 --vertices 6 --radius1 0.1 --radius2 0 --depth 0.22 --location 0 0 0.37
select A0 A1
active A0
join
set rotation 0 28 0
apply --rotation
set location 0.17 0.04 0.12
apply --location
add mesh cylinder --name B0 --vertices 6 --radius 0.09 --depth 0.2 --location 0 0 0.1
add mesh cone --name B1 --vertices 6 --radius1 0.09 --radius2 0 --depth 0.2 --location 0 0 0.3
select B0 B1
active B0
join
set rotation 0 -32 20
apply --rotation
set location -0.16 -0.05 0.12
apply --location
select M0 M1 A0 B0
active M0
join
rename M0 Shard
material assign Shard
select Plinth Shard
shade flat
export crystal.glb
"""

# ---------------------------------------------------------------- stump (a broken pillar: blocks the beam)
files["stump"] = f"""# Stump: a broken octagonal pillar on a square base, its top jagged. Blocks the beam.
# Generated by make_env.py.
new
material new Stone {col('B')} --no-slot
material new Cap {col('C')} --no-slot
{box('Base', 0.8, 0.8, 0.16, 0, 0, 0.08)}add mesh cylinder --name Shaft --vertices 8 --radius 0.3 --depth 1.0 --location 0 0 0.62
mode edit
select vert where "pos.z > 0.4"
randomize --amount 0.16 --seed 11
mode object
select Base Shaft
active Base
join
rename Base Stump
material assign Stone
mode edit
select face where "normal.z > 0.7"
material assign Cap
select face where "normal.z < -0.9"
delete only-faces
mode object
shade flat
export stump.glb
"""

# ---------------------------------------------------------------- lens (the sunbeam's source, west of the court)
files["lens"] = f"""# Lens: a stone post holding a glowing prism at the beam's height (1.27 m), the source of the
# sunbeam on the court's west side. Generated by make_env.py.
new
material new Stone {col('B')} --no-slot
material new Glow {col('E')} --no-slot
{box('Post', 0.22, 0.22, 1.12, 0, 0, 0.56)}{box('Foot', 0.5, 0.5, 0.12, 0, 0, 0.06)}select Post Foot
active Post
join
material assign Stone
mode edit
select face where "normal.z < -0.9"
delete only-faces
mode object
add mesh ico-sphere --name Prism --subdivisions 1 --radius 0.2 --location 0 0 1.27
scale 1 1 1.2
apply --scale
material assign Glow
select Post Prism
shade flat
export lens.glb
"""

# ---------------------------------------------------------------- spark, ring, emblem
files["spark"] = f"""# Spark: a tiny icosahedron of light (pops, the beam's splash). Generated by make_env.py.
new
material new Spark {col('E')} --no-slot
add mesh ico-sphere --name Spark --subdivisions 1 --radius 0.09 --location 0 0 0
material assign Spark
shade flat
export spark.glb
"""
files["ring"] = f"""# Ring: a flat octagonal ring on the floor round a mirror, the hover marker. Generated by make_env.py.
new
material new Ring {col('D')} --no-slot
add mesh torus --name Ring --major-segments 8 --minor-segments 4 --major-radius 0.56 --minor-radius 0.06 --location 0 0 0.03
scale 1 1 0.4
apply --scale
material assign Ring
shade flat
export ring.glb
"""
files["emblem"] = f"""# Emblem: the sun disc over the temple gate (a 12-sided disc with two wing slabs), facing the court.
# Baked twice: dark stone, and glowing when a puzzle is solved. Generated by make_env.py.
new
material new Disc {col('C')} --no-slot
add mesh cylinder --name Disc --vertices 12 --radius 0.42 --depth 0.14 --location 0 0 0
set rotation 90 0 0
apply --rotation
{box('WingL', 0.75, 0.1, 0.2, -0.75, 0, 0.06)}{box('WingR', 0.75, 0.1, 0.2, 0.75, 0, 0.06)}select Disc WingL WingR
active Disc
join
material assign Disc
shade flat
export emblem.glb
"""

for n, s in files.items():
    open(f"{n}.txt", "w").write(s)
print("wrote", ", ".join(f"{n}.txt" for n in files))
